    } catch (error) {
        console.error('[DEBUG] Error updating item:', error);
        statusDiv.textContent = `\❌ Error: ${error.message}`;
        statusDiv.style.color = '#dc3545';
        if (adoptBtn) {
            adoptBtn.disabled = false;
