    function drawBranch(level) {
      if (level > maxLevels) return;
      ctx.strokeStyle = colors[level % colors.length] || "#000000";
      ctx.lineWidth = maxLevels - level + 1;
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(0, -branchLength);
      ctx.stroke();
      ctx.translate(0, -branchLength);
      ctx.save();
      ctx.rotate(-0.5);
      drawBranch(level + 1);
      ctx.restore();
      ctx.save();
      ctx.rotate(0.5);
      drawBranch(level + 1);
      ctx.restore();
    }
    drawBranch(0);
