     * Gets and caches the location of a uniform variable in the shader.
     * @param {string} name
     */
    getUniformLocation(name) {
        if (!this.uniforms[name]) {
            this.uniforms[name] = this.gl.getUniformLocation(this.program, name);
        }
        return this.uniforms[name];
    }
}
