// FILE: netlify/functions/ai-project-manager.js
// AI Strategic Project Manager - Analyzes business status and generates actionable roadmaps

const fetch = require('node-fetch');

const { AIRTABLE_PAT, BASE_ID, GEMINI_API_KEY } = process.env;

// Airtable table names - these must match exactly what was created in Airtable
const BUSINESS_CONTEXT_TABLE = 'Business_Context';
const STRATEGIC_TASKS_TABLE = 'Strategic_Tasks';

/**
 * Extracts a JSON object from a string, even if it's wrapped in markdown.
 * @param {string} text - The raw text response from the AI.
 * @returns {object} The parsed JSON object.
 */
function cleanAndParseGeminiJson(text) {
    console.log('[Debug] Raw Gemini Text:', text);
    const jsonMatch = text.match(/{[\s\S]*}/);
    if (!jsonMatch) {
        throw new Error('Gemini response did not contain a valid JSON object.');
    }
    const jsonString = jsonMatch[0];
    try {
        return JSON.parse(jsonString);
    } catch (parseError) {
        console.error('[Debug] Failed to parse extracted JSON:', parseError);
        throw new Error(`Failed to parse AI response as JSON: ${parseError.message}`);
    }
}

/**
 * Fetches the last 5 business context records from Airtable for historical context.
 * @returns {Promise<Array>} Array of recent context records.
 */
async function fetchBusinessHistory() {
    console.log('[Debug] Fetching business history from Airtable...');

    const url = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(BUSINESS_CONTEXT_TABLE)}?maxRecords=5&sort[0][field]=Timestamp&sort[0][direction]=desc`;

    try {
        const response = await fetch(url, {
            headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
        });

        if (!response.ok) {
            const errorText = await response.text();
            console.warn('[Debug] Could not fetch business history:', errorText);
            return []; // Return empty array if table doesn't exist or has no records
        }

        const data = await response.json();
        console.log(`[Debug] Retrieved ${data.records?.length || 0} historical context records.`);
        return data.records || [];
    } catch (error) {
        console.warn('[Debug] Error fetching business history:', error.message);
        return [];
    }
}

/**
 * Formats historical context records into a text block for the AI prompt.
 * @param {Array} records - Array of Airtable records.
 * @returns {string} Formatted history text.
 */
function formatHistoryForPrompt(records) {
    if (!records || records.length === 0) {
        return 'No previous business context available. This is the first strategic analysis.';
    }

    const historyLines = records.map((record, index) => {
        const fields = record.fields;
        const timestamp = fields.Timestamp || 'Unknown date';
        const update = fields.UpdateText || 'No update text';
        const summary = fields.AnalysisSummary || 'No summary';
        return `[${index + 1}] ${timestamp}:\nInput: ${update}\nAnalysis: ${summary}`;
    });

    return historyLines.join('\n\n');
}

/**
 * Calls Google Gemini to analyze business input and generate strategic tasks.
 * @param {string} userInput - The business status/brain dump from the user.
 * @param {string} historyContext - Formatted historical context.
 * @returns {Promise<object>} Parsed strategic analysis JSON.
 */
async function analyzeWithGemini(userInput, historyContext) {
    console.log('[Debug] Calling Gemini for strategic analysis...');

    if (!GEMINI_API_KEY) {
        throw new Error('Server configuration error: Missing GEMINI_API_KEY.');
    }

    const systemPrompt = `
You are an expert AI Strategic Project Manager for small business owners. Your role is to analyze unstructured business updates and generate a focused, actionable roadmap.

## HISTORICAL CONTEXT
Here are the last few business updates and analyses for continuity:
${historyContext}

## CURRENT USER INPUT
The business owner has provided this status update:
"${userInput}"

## YOUR TASK
Analyze the current input in the context of the business history. Generate 3-5 HIGH-IMPACT strategic tasks that address the core issues.

## OUTPUT FORMAT
Respond ONLY with a valid JSON object. Do not include markdown \`\`\`json or any text before or after the JSON.

The JSON MUST have this exact structure:
{
  "summary": "A 1-sentence strategic overview of the current situation and recommended focus.",
  "tasks": [
    {
      "TaskName": "Clear, actionable task name",
      "Type": "Short Term Fix|Long Term Strategy|Operational Improvement",
      "BusinessHealthBenefit": "Explicit ROI or business health impact (e.g., 'Increase revenue by 15%', 'Reduce churn by 20%')",
      "SuccessCriteria": "Measurable KPI or outcome that defines success",
      "TargetHours": 8,
      "Priority": "High|Medium|Low"
    }
  ]
}

## GUIDELINES
1. **Focus on Impact**: Each task should directly address a pain point or opportunity mentioned in the input.
2. **Be Specific**: Avoid vague tasks. "Improve marketing" is bad. "Launch email campaign targeting lapsed customers" is good.
3. **Include Mix**: Provide a balance of quick wins (Short Term Fix) and foundational improvements (Long Term Strategy).
4. **Realistic Estimates**: TargetHours should reflect actual effort for a small team.
5. **ROI Focus**: BusinessHealthBenefit should explicitly state expected outcomes.

Generate the strategic roadmap now.
`;

    const payload = {
        contents: [
            {
                parts: [{ text: systemPrompt }]
            }
        ],
        generationConfig: {
            temperature: 0.7,
            maxOutputTokens: 2048
        }
    };

    const apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${GEMINI_API_KEY}`;

    const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorBody = await response.text();
        console.error('[Debug] Gemini API Error:', errorBody);
        throw new Error(`Gemini API call failed with status ${response.status}`);
    }

    const result = await response.json();
    console.log('[Debug] Gemini response received.');

    let jsonText = '';
    try {
        jsonText = result.candidates[0].content.parts[0].text;
    } catch (e) {
        console.error('[Debug] Error extracting text from Gemini response:', JSON.stringify(result, null, 2));
        throw new Error('Could not extract text from Gemini response.');
    }

    return cleanAndParseGeminiJson(jsonText);
}

/**
 * Saves the business context to Airtable.
 * @param {string} updateText - The user's original input.
 * @param {string} analysisSummary - The AI-generated summary.
 * @returns {Promise<object>} The created record.
 */
async function saveBusinessContext(updateText, analysisSummary) {
    console.log('[Debug] Saving business context to Airtable...');

    const url = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(BUSINESS_CONTEXT_TABLE)}`;

    const payload = {
        fields: {
            UpdateText: updateText,
            AnalysisSummary: analysisSummary,
            Timestamp: new Date().toISOString()
        }
    };

    const response = await fetch(url, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${AIRTABLE_PAT}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(payload)
    });

    if (!response.ok) {
        const errorText = await response.text();
        console.error('[Debug] Failed to save business context:', errorText);
        throw new Error(`Failed to save business context: ${response.status}`);
    }

    const record = await response.json();
    console.log('[Debug] Business context saved. Record ID:', record.id);
    return record;
}

/**
 * Saves strategic tasks to Airtable.
 * @param {Array} tasks - Array of task objects from AI analysis.
 * @returns {Promise<Array>} Array of created records.
 */
async function saveStrategicTasks(tasks) {
    console.log(`[Debug] Saving ${tasks.length} strategic tasks to Airtable...`);

    const url = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(STRATEGIC_TASKS_TABLE)}`;

    // Airtable allows up to 10 records per batch request
    const records = tasks.map(task => ({
        fields: {
            TaskName: task.TaskName,
            Type: task.Type,
            BusinessHealthBenefit: task.BusinessHealthBenefit,
            SuccessCriteria: task.SuccessCriteria,
            TargetHours: task.TargetHours,
            Priority: task.Priority,
            Status: 'Proposed',
            CreatedAt: new Date().toISOString()
        }
    }));

    const response = await fetch(url, {
        method: 'POST',
        headers: {
            'Authorization': `Bearer ${AIRTABLE_PAT}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({ records })
    });

    if (!response.ok) {
        const errorText = await response.text();
        console.error('[Debug] Failed to save strategic tasks:', errorText);
        throw new Error(`Failed to save strategic tasks: ${response.status}`);
    }

    const result = await response.json();
    console.log(`[Debug] Successfully saved ${result.records?.length || 0} tasks.`);
    return result.records;
}

/**
 * Main handler for the AI Project Manager function.
 */
exports.handler = async (event) => {
    console.log(`[Debug] /api/ai-project-manager handler invoked. Method: ${event.httpMethod}`);

    // Only allow POST requests
    if (event.httpMethod !== 'POST') {
        return {
            statusCode: 405,
            body: JSON.stringify({ error: 'Method Not Allowed. Use POST.' })
        };
    }

    try {
        // 1. Parse the incoming request
        const { userInput } = JSON.parse(event.body || '{}');

        if (!userInput || typeof userInput !== 'string' || userInput.trim().length === 0) {
            return {
                statusCode: 400,
                body: JSON.stringify({ error: 'Missing or empty userInput field.' })
            };
        }

        console.log(`[Debug] Received user input (${userInput.length} chars).`);

        // 2. Fetch historical business context
        const historyRecords = await fetchBusinessHistory();
        const historyContext = formatHistoryForPrompt(historyRecords);

        // 3. Call Gemini for strategic analysis
        const analysis = await analyzeWithGemini(userInput.trim(), historyContext);

        if (!analysis.summary || !Array.isArray(analysis.tasks)) {
            throw new Error('Invalid AI response structure. Missing summary or tasks.');
        }

        console.log(`[Debug] AI generated ${analysis.tasks.length} strategic tasks.`);

        // 4. Save the business context
        await saveBusinessContext(userInput.trim(), analysis.summary);

        // 5. Save the strategic tasks
        if (analysis.tasks.length > 0) {
            await saveStrategicTasks(analysis.tasks);
        }

        // 6. Return the analysis to the frontend
        return {
            statusCode: 200,
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                success: true,
                summary: analysis.summary,
                tasks: analysis.tasks
            })
        };

    } catch (error) {
        console.error('[ERROR] /api/ai-project-manager handler failed:', error.message, error.stack);
        return {
            statusCode: 500,
            body: JSON.stringify({
                error: `Analysis failed: ${error.message}`
            })
        };
    }
};

// FILE: netlify/functions/airtable.js
// PURPOSE: This function now securely fetches the item list for the admin profiler.

const fetch = require('node-fetch');
const { AIRTABLE_PAT, BASE_ID } = process.env;

const ITEMS_TABLE = 'tblUA4uuS8IYlhKpD';

exports.handler = async (event) => {
    if (event.httpMethod !== 'GET') {
        return {
            statusCode: 405,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ error: 'Method Not Allowed' })
        };
    }

    // Validate environment variables
    if (!AIRTABLE_PAT || !BASE_ID) {
        console.error("[get-items-for-profiling] Missing required environment variables");
        return {
            statusCode: 500,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ error: 'Server configuration error' })
        };
    }

    try {
        console.log("[get-items-for-profiling] Fetching all items from Airtable...");
        let allRecords = [];
        let offset = null;
        let pageCount = 0;
        const MAX_PAGES = 100; // Safety limit to prevent infinite loops

        // We only fetch Name and the new AI_Profile field
        const fieldsQuery = `fields%5B%5D=Name&fields%5B%5D=AI_Profile`;
        const baseUrl = `https://api.airtable.com/v0/${BASE_ID}/${ITEMS_TABLE}?${fieldsQuery}`;

        do {
            pageCount++;
            if (pageCount > MAX_PAGES) {
                console.error(`[get-items-for-profiling] Exceeded maximum page limit of ${MAX_PAGES}`);
                throw new Error('Too many records to fetch');
            }

            let url = baseUrl;
            if (offset) {
                url += `&offset=${encodeURIComponent(offset)}`;
            }

            // Add timeout to prevent hanging requests
            const controller = new AbortController();
            const timeout = setTimeout(() => controller.abort(), 15000); // 15 second timeout

            const response = await fetch(url, {
                headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` },
                signal: controller.signal
            });
            clearTimeout(timeout);

            if (!response.ok) {
                const errorText = await response.text();
                console.error(`[get-items-for-profiling] Airtable Error:`, errorText);
                throw new Error(`Failed to fetch items. Status: ${response.status}`);
            }

            const data = await response.json();

            // Validate response structure
            if (!data.records || !Array.isArray(data.records)) {
                throw new Error('Invalid response structure from Airtable');
            }

            allRecords = allRecords.concat(data.records);
            offset = data.offset;
        } while (offset);

        console.log(`[get-items-for-profiling] Total item records fetched: ${allRecords.length}`);

        return {
            statusCode: 200,
            headers: {
                'Content-Type': 'application/json',
                'Cache-Control': 'private, max-age=60' // Cache for 1 minute
            },
            body: JSON.stringify(allRecords)
        };

    } catch (error) {
        console.error("[get-items-for-profiling] Function Error:", error.message);

        // Handle specific error types
        if (error.name === 'AbortError') {
            return {
                statusCode: 504,
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ error: 'Request timeout while fetching items' })
            };
        }

        return {
            statusCode: 500,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ error: error.message || 'Internal server error' })
        };
    }
};

// CREATE A NEW FILE AT: netlify/functions/associate-session.js

const fetch = require('node-fetch');
const { AIRTABLE_PAT, BASE_ID } = process.env;

// Helper function to prevent duplicate IDs in an array
const addUniqueId = (array, id) => {
  const set = new Set(array || []);
  set.add(id);
  return Array.from(set);
};

exports.handler = async (event) => {
  if (event.httpMethod !== 'POST') {
    return { statusCode: 405, body: 'Method Not Allowed' };
  }

  try {
    const { userId, sessionId } = JSON.parse(event.body);
    if (!userId || !sessionId) {
      return { statusCode: 400, body: JSON.stringify({ error: 'User ID and Session ID are required.' }) };
    }

    // 1. Fetch both the user and session records in parallel
    const userUrl = `https://api.airtable.com/v0/${BASE_ID}/Users/${userId}`;
    const sessionUrl = `https://api.airtable.com/v0/${BASE_ID}/Sessions/${sessionId}`;

    const [userResponse, sessionResponse] = await Promise.all([
      fetch(userUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } }),
      fetch(sessionUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } })
    ]);

    if (!userResponse.ok || !sessionResponse.ok) {
      throw new Error('Could not fetch user or session record from Airtable.');
    }

    const userRecord = await userResponse.json();
    const sessionRecord = await sessionResponse.json();

    // 2. Update the User record to link to the Session
    const updatedUserPayload = {
      records: [{
        id: userId,
        fields: { 'Associated Sessions': addUniqueId(userRecord.fields['Associated Sessions'], sessionId) }
      }]
    };
    const updateUserPromise = fetch(`https://api.airtable.com/v0/${BASE_ID}/Users`, {
      method: 'PATCH',
      headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(updatedUserPayload)
    });

    // 3. Update the Session record to link to the User (as a collaborator)
    const updatedSessionPayload = {
      records: [{
        id: sessionId,
        fields: { 'Collaborators': addUniqueId(sessionRecord.fields['Collaborators'], userId) }
      }]
    };
    const updateSessionPromise = fetch(`https://api.airtable.com/v0/${BASE_ID}/Sessions`, {
      method: 'PATCH',
      headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(updatedSessionPayload)
    });

    // 4. Run both updates and wait for them to complete
    await Promise.all([updateUserPromise, updateSessionPromise]);

    return {
      statusCode: 200,
      body: JSON.stringify({ message: 'Session associated successfully.' }),
    };

  } catch (error) {
    console.error('Associate session error:', error);
    return {
      statusCode: 500,
      body: JSON.stringify({ error: error.message }),
    };
  }
};

// REPLACE THE ENTIRE CONTENTS OF: netlify/functions/auth-confirm.js

const fetch = require('node-fetch');
const jwt = require('jsonwebtoken');
const Pusher = require("pusher");
const { AIRTABLE_PAT, BASE_ID, JWT_SECRET, PUSHER_APP_ID, PUSHER_KEY, PUSHER_SECRET, PUSHER_CLUSTER } = process.env;

const pusher = new Pusher({
    appId: PUSHER_APP_ID,
    key: PUSHER_KEY,
    secret: PUSHER_SECRET,
    cluster: PUSHER_CLUSTER,
    useTLS: true,
});

exports.handler = async (event) => {
    try {
        const { token } = event.queryStringParameters;
        if (!token) throw new Error('Token is required.');

        const findTokenUrl = `https://api.airtable.com/v0/${BASE_ID}/Magic%20Links?filterByFormula=AND({Token}='${token}')`;
        const tokenRes = await fetch(findTokenUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        const tokenData = await tokenRes.json();
        if (!tokenData.records || tokenData.records.length === 0) throw new Error('Invalid or expired token.');

        const magicLinkRecord = tokenData.records[0];
        const { Email, ExpiresAt, ChannelID } = magicLinkRecord.fields;

        if (new Date() > new Date(ExpiresAt)) throw new Error('Invalid or expired token.');
        await fetch(`https://api.airtable.com/v0/${BASE_ID}/Magic%20Links/${magicLinkRecord.id}`, { method: 'DELETE', headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });

        const findUserUrl = `https://api.airtable.com/v0/${BASE_ID}/Users?filterByFormula=AND({Email}='${Email}')`;
        const userRes = await fetch(findUserUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        let userData = await userRes.json();
        let userRecord;

        if (userData.records && userData.records.length > 0) {
            userRecord = userData.records[0];
        } else {
            const createUserRes = await fetch(`https://api.airtable.com/v0/${BASE_ID}/Users`, {
                method: 'POST',
                headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}`, 'Content-Type': 'application/json' },
                body: JSON.stringify({ records: [{ fields: { Email: Email, Name: Email.split('@')[0] } }] })
            });
            const newUserData = await createUserRes.json();
            userRecord = newUserData.records[0];
        }

        let ownerData = { isOwner: false, ownerDashboardId: null };
        if (userRecord.fields.OwnedStore && userRecord.fields.OwnedStore.length > 0) {
            const storeId = userRecord.fields.OwnedStore[0];
            const storeUrl = `https://api.airtable.com/v0/${BASE_ID}/Stores/${storeId}`;
            const storeRes = await fetch(storeUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
            if (storeRes.ok) {
                const storeRecord = await storeRes.json();
                if (storeRecord.fields.OwnerDashboardID) {
                    ownerData.isOwner = true;
                    ownerData.ownerDashboardId = storeRecord.fields.OwnerDashboardID;
                }
            }
        }

        // *** FETCH SESSION NAMES ***
        let associatedSessions = [];
        const sessionIds = userRecord.fields['Associated Sessions'];
        if (sessionIds && sessionIds.length > 0) {
            const formula = `OR(${sessionIds.map(id => `RECORD_ID()='${id}'`).join(',')})`;
            const sessionsUrl = `https://api.airtable.com/v0/${BASE_ID}/Sessions?fields%5B%5D=Name&filterByFormula=${encodeURIComponent(formula)}`;
            const sessionsRes = await fetch(sessionsUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
            if (sessionsRes.ok) {
                const sessionsData = await sessionsRes.json();
                associatedSessions = sessionsData.records.map(rec => ({ id: rec.id, name: rec.fields.Name }));
            }
        }

        // *** FETCH LIKED ITEMS ***
        const ITEMS_TABLE = 'tblUA4uuS8IYlhKpD';
        const LIKED_BY_FIELD = 'Liked By Users';
        const RSVPS_FIELD = 'RSVPs';

        let likedItemIds = [];
        const likedItemsFormula = `FIND('${userRecord.id}', ARRAYJOIN({${LIKED_BY_FIELD}}))`;
        const likedItemsUrl = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(ITEMS_TABLE)}?filterByFormula=${encodeURIComponent(likedItemsFormula)}&fields[]=`;
        const likedItemsRes = await fetch(likedItemsUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        if (likedItemsRes.ok) {
            const likedItemsData = await likedItemsRes.json();
            likedItemIds = likedItemsData.records ? likedItemsData.records.map(rec => rec.id) : [];
        }

        // *** FETCH RSVP'D ITEMS ***
        let rsvpdItemIds = [];
        const rsvpdItemsFormula = `FIND('${userRecord.id}', ARRAYJOIN({${RSVPS_FIELD}}))`;
        const rsvpdItemsUrl = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(ITEMS_TABLE)}?filterByFormula=${encodeURIComponent(rsvpdItemsFormula)}&fields[]=`;
        const rsvpdItemsRes = await fetch(rsvpdItemsUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });
        if (rsvpdItemsRes.ok) {
            const rsvpdItemsData = await rsvpdItemsRes.json();
            rsvpdItemIds = rsvpdItemsData.records ? rsvpdItemsData.records.map(rec => rec.id) : [];
        }

        const sessionToken = jwt.sign(
            { userId: userRecord.id, name: userRecord.fields.Name, email: userRecord.fields.Email, isOwner: ownerData.isOwner }, 
            JWT_SECRET, 
            { expiresIn: '30d' }
        );

        await pusher.trigger(`private-auth-${ChannelID}`, "auth-success", {
            token: sessionToken,
            user: {
                id: userRecord.id,
                name: userRecord.fields.Name,
                email: userRecord.fields.Email,
                phoneNumber: userRecord.fields.PhoneNumber || '',
                notificationFrequency: userRecord.fields.NotificationFrequency || 'None',
                likedItemIds: likedItemIds,
                rsvpdItemIds: rsvpdItemIds
            },
            ownerData: ownerData,
            associatedSessions: associatedSessions
        });

        return {
            statusCode: 200,
            headers: { 'Content-Type': 'text/html' },
            body: `<div style="font-family: sans-serif; text-align: center; padding-top: 50px;"><h1>Authentication Confirmed!</h1><p>You can now return to the original tab to continue.</p></div>`
        };
    } catch (error) {
        console.error('Auth-confirm error:', error);
        return {
            statusCode: 400,
            headers: { 'Content-Type': 'text/html' },
            body: `<div style="font-family: sans-serif; text-align: center; padding-top: 50px;"><h1>Authentication Failed</h1><p>${error.message}. Please try again.</p></div>`
        };
    }
};

// SMS-based authentication starter
// Sends a 6-digit OTP code via SMS using Twilio

const fetch = require('node-fetch');
const twilio = require('twilio');
const crypto = require('crypto');

const {
  AIRTABLE_PAT,
  BASE_ID,
  TWILIO_ACCOUNT_SID,
  TWILIO_AUTH_TOKEN,
  TWILIO_PHONE_NUMBER
} = process.env;

const twilioClient = twilio(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN);

exports.handler = async (event) => {
    console.log('[SMS-START-DEBUG] ========== Function invoked ==========');
    console.log('[SMS-START-DEBUG] HTTP Method:', event.httpMethod);
    console.log('[SMS-START-DEBUG] Request headers:', JSON.stringify(event.headers));
    console.log('[SMS-START-DEBUG] Request body (raw):', event.body);

    if (event.httpMethod !== 'POST') {
        console.log('[SMS-START-DEBUG] Invalid HTTP method - returning 405');
        return { statusCode: 405, body: 'Method Not Allowed' };
    }

    try {
        console.log('[SMS-START-DEBUG] Parsing request body');
        const { phoneNumber } = JSON.parse(event.body);
        console.log('[SMS-START-DEBUG] Parsed phoneNumber:', phoneNumber);

        if (!phoneNumber) {
            console.log('[SMS-START-DEBUG] Phone number validation failed - returning 400');
            return {
                statusCode: 400,
                body: JSON.stringify({ error: 'Phone number is required.' })
            };
        }

        // Normalize phone number (ensure it starts with +)
        const normalizedPhone = phoneNumber.startsWith('+') ? phoneNumber : `+${phoneNumber}`;
        console.log('[SMS-START-DEBUG] Normalized phone number:', normalizedPhone);

        console.log(`[auth-sms-start] SMS auth requested for: ${normalizedPhone}`);

        // Check environment variables
        console.log('[SMS-START-DEBUG] Environment variable checks:');
        console.log('[SMS-START-DEBUG] - TWILIO_ACCOUNT_SID exists:', !!TWILIO_ACCOUNT_SID);
        console.log('[SMS-START-DEBUG] - TWILIO_AUTH_TOKEN exists:', !!TWILIO_AUTH_TOKEN);
        console.log('[SMS-START-DEBUG] - TWILIO_PHONE_NUMBER exists:', !!TWILIO_PHONE_NUMBER);
        console.log('[SMS-START-DEBUG] - TWILIO_PHONE_NUMBER value:', TWILIO_PHONE_NUMBER);
        console.log('[SMS-START-DEBUG] - AIRTABLE_PAT exists:', !!AIRTABLE_PAT);
        console.log('[SMS-START-DEBUG] - BASE_ID exists:', !!BASE_ID);

        // Check if user has opted out
        console.log('[SMS-START-DEBUG] Checking opt-out status...');
        const optOutCheckUrl = `https://api.airtable.com/v0/${BASE_ID}/SMS%20Opt-Outs?filterByFormula=({PhoneNumber}='${normalizedPhone}')`;

        try {
            const optOutResponse = await fetch(optOutCheckUrl, {
                headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
            });

            if (optOutResponse.ok) {
                const optOutData = await optOutResponse.json();
                console.log('[SMS-START-DEBUG] Opt-out check response:', JSON.stringify(optOutData));

                if (optOutData.records && optOutData.records.length > 0) {
                    console.log('[SMS-START-DEBUG] User has opted out - blocking SMS');
                    return {
                        statusCode: 403,
                        body: JSON.stringify({
                            error: 'This phone number has opted out of SMS messages. Please reply START to your last message to opt back in, or use a different sign-in method.'
                        })
                    };
                }
                console.log('[SMS-START-DEBUG] No opt-out found - proceeding');
            }
        } catch (optOutError) {
            console.error('[SMS-START-DEBUG] Error checking opt-out status:', optOutError);
            // Continue anyway - don't block on opt-out check failure
        }

        // Generate 6-digit OTP code
        const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
        const channelId = crypto.randomBytes(12).toString('hex'); // For real-time confirmation
        const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // OTP expires in 10 minutes

        console.log(`[auth-sms-start] Generated OTP: ${otpCode} (expires: ${expiresAt.toISOString()})`);
        console.log('[SMS-START-DEBUG] Channel ID:', channelId);

        // Store the OTP code in Airtable
        const airtableUrl = `https://api.airtable.com/v0/${BASE_ID}/SMS%20Codes`;
        console.log('[SMS-START-DEBUG] Airtable URL:', airtableUrl);
        console.log('[SMS-START-DEBUG] Storing OTP in Airtable...');

        // Build fields object - start with required fields only
        const fields = {
            Code: otpCode,
            PhoneNumber: normalizedPhone,
            ExpiresAt: expiresAt.toISOString(),
            ChannelID: channelId
        };

        // Try to add consent fields, but don't fail if they don't work
        // The first request will try with consent fields
        const airtablePayload = {
            records: [{
                fields: {
                    ...fields,
                    ConsentGranted: true,
                    ConsentTimestamp: new Date().toISOString(),
                    ConsentSource: 'web_form'
                }
            }]
        };
        console.log('[SMS-START-DEBUG] Airtable payload (with consent fields):', JSON.stringify(airtablePayload));

        const airtableResponse = await fetch(airtableUrl, {
            method: 'POST',
            headers: {
                'Authorization': `Bearer ${AIRTABLE_PAT}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(airtablePayload)
        });

        console.log('[SMS-START-DEBUG] Airtable response status:', airtableResponse.status);
        console.log('[SMS-START-DEBUG] Airtable response ok:', airtableResponse.ok);

        let airtableData; // Declare outside so it's available for cleanup later

        if (!airtableResponse.ok) {
            const errorText = await airtableResponse.text();
            console.error('[auth-sms-start] Airtable error status:', airtableResponse.status);
            console.error('[SMS-START-DEBUG] Full Airtable error response (text):', errorText);

            let errorData;
            try {
                errorData = JSON.parse(errorText);
                console.error('[SMS-START-DEBUG] Parsed error data:', JSON.stringify(errorData, null, 2));
            } catch (e) {
                console.error('[SMS-START-DEBUG] Could not parse error as JSON');
            }

            // Check if the error is about unknown fields (consent fields might not exist)
            const errorMessage = errorData?.error?.message || errorText || '';

            // Handle different types of Airtable errors
            if (errorMessage.includes('Could not find table')) {
                console.error('[SMS-START-DEBUG] SMS Codes table does not exist in Airtable');
                throw new Error('SMS authentication is not configured. Please create the "SMS Codes" table in Airtable with fields: Code, PhoneNumber, ExpiresAt, ChannelID');
            }

            if (errorMessage.includes('Unknown field name') || errorMessage.includes('field')) {
                console.log('[SMS-START-DEBUG] Field error detected - retrying without consent fields');

                // Retry without consent fields
                const simplePayload = {
                    records: [{
                        fields: fields // Just the basic required fields
                    }]
                };
                console.log('[SMS-START-DEBUG] Retrying with simple payload:', JSON.stringify(simplePayload));

                const retryResponse = await fetch(airtableUrl, {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${AIRTABLE_PAT}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(simplePayload)
                });

                console.log('[SMS-START-DEBUG] Retry response status:', retryResponse.status);

                if (!retryResponse.ok) {
                    const retryErrorText = await retryResponse.text();
                    console.error('[SMS-START-DEBUG] Retry also failed:', retryErrorText);
                    throw new Error(`Airtable error after retry: ${retryErrorText}`);
                }

                // Success on retry!
                airtableData = await retryResponse.json();
                console.log('[auth-sms-start] OTP stored in Airtable successfully (without consent fields).');
                console.log('[SMS-START-DEBUG] Airtable response data:', JSON.stringify(airtableData));
            } else {
                // Different error, not about fields
                const errorMsg = errorData?.error?.message || errorData?.error || 'Could not store SMS code in database.';
                throw new Error(`Airtable error: ${errorMsg}`);
            }
        } else {
            // First attempt succeeded
            airtableData = await airtableResponse.json();
            console.log('[auth-sms-start] OTP stored in Airtable successfully.');
            console.log('[SMS-START-DEBUG] Airtable response data:', JSON.stringify(airtableData));
        }

        // Send SMS via Twilio
        const smsBody = `Your WTFun authentication code is: ${otpCode}

This code expires in 10 minutes. Reply STOP to opt out. Msg&data rates may apply.`;
        console.log('[SMS-START-DEBUG] SMS body to send:', smsBody);
        console.log('[SMS-START-DEBUG] Sending SMS from:', TWILIO_PHONE_NUMBER, 'to:', normalizedPhone);

        try {
            console.log('[SMS-START-DEBUG] Calling Twilio API...');
            const message = await twilioClient.messages.create({
                body: smsBody,
                from: TWILIO_PHONE_NUMBER,
                to: normalizedPhone
            });

            console.log(`[auth-sms-start] SMS sent successfully. SID: ${message.sid}`);
            console.log('[SMS-START-DEBUG] Twilio message status:', message.status);
            console.log('[SMS-START-DEBUG] Twilio message error_code:', message.error_code);
            console.log('[SMS-START-DEBUG] Twilio message error_message:', message.error_message);
            console.log('[SMS-START-DEBUG] Full Twilio response:', JSON.stringify(message));
        } catch (twilioError) {
            console.error('[auth-sms-start] Twilio error:', twilioError);
            console.error('[SMS-START-DEBUG] Twilio error name:', twilioError.name);
            console.error('[SMS-START-DEBUG] Twilio error message:', twilioError.message);
            console.error('[SMS-START-DEBUG] Twilio error code:', twilioError.code);
            console.error('[SMS-START-DEBUG] Twilio error status:', twilioError.status);
            console.error('[SMS-START-DEBUG] Twilio error stack:', twilioError.stack);
            console.error('[SMS-START-DEBUG] Full Twilio error object:', JSON.stringify(twilioError, null, 2));

            // Clean up the stored code if SMS fails
            console.log('[SMS-START-DEBUG] Cleaning up stored OTP code due to Twilio error...');
            if (airtableData.records && airtableData.records[0]) {
                const deleteUrl = `https://api.airtable.com/v0/${BASE_ID}/SMS%20Codes/${airtableData.records[0].id}`;
                console.log('[SMS-START-DEBUG] Delete URL:', deleteUrl);
                try {
                    const deleteResponse = await fetch(deleteUrl, {
                        method: 'DELETE',
                        headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
                    });
                    console.log('[SMS-START-DEBUG] Cleanup response status:', deleteResponse.status);
                } catch (err) {
                    console.error('[auth-sms-start] Cleanup error:', err);
                    console.error('[SMS-START-DEBUG] Cleanup error details:', JSON.stringify(err));
                }
            }

            throw new Error('Failed to send SMS. Please check the phone number and try again.');
        }

        // Return success with channelId for real-time confirmation
        const successResponse = {
            message: 'SMS code sent successfully.',
            channelId: channelId
        };
        console.log('[SMS-START-DEBUG] Returning success response:', JSON.stringify(successResponse));
        console.log('[SMS-START-DEBUG] ========== Function completed successfully ==========');

        return {
            statusCode: 200,
            body: JSON.stringify(successResponse),
        };
    } catch (error) {
        console.error('[auth-sms-start] Error:', error);
        console.error('[SMS-START-DEBUG] ========== ERROR IN FUNCTION ==========');
        console.error('[SMS-START-DEBUG] Error name:', error.name);
        console.error('[SMS-START-DEBUG] Error message:', error.message);
        console.error('[SMS-START-DEBUG] Error stack:', error.stack);
        console.error('[SMS-START-DEBUG] Full error object:', JSON.stringify(error, null, 2));

        return {
            statusCode: 500,
            body: JSON.stringify({
                error: error.message || 'An internal error occurred.'
            }),
        };
    }
};

